from datetime import datetime, timezone

def american_probability(value):
    """Calculate implied probability from American odds.

    Args:
        value: A numeric value (int, float, or numeric string).

    Returns:
        The implied probability as a float.

    Raises:
        ValueError: If the input is not a finite number with absolute value >= 100,
                    or if it's a boolean or None.
    """
    # Check for boolean or None explicitly
    if isinstance(value, bool):
        raise ValueError("Input cannot be a boolean")
    if value is None:
        raise ValueError("Input cannot be None")

    # Attempt to convert to float
    try:
        num = float(value)
    except (TypeError, ValueError):
        raise ValueError("Input must be a numeric value")

    # Check for finiteness and absolute value >= 100
    if not isinstance(num, float) or not num.is_finite():
        raise ValueError("Input must be a finite number")
    if abs(num) < 100:
        raise ValueError("Absolute value of input must be >= 100")

    # Calculate probability based on sign
    if num > 0:
        return 100 / (num + 100)
    else:
        return -num / (-num + 100)
